css_snippet:
.single-line-text {
  white-space: nowrap; /* Prevents text from wrapping to the next line */
  overflow: hidden; /* Hides any text that overflows the container */
  text-overflow: ellipsis; /* Displays an ellipsis (...) to indicate clipped text */
}

.pre-formatted-content {
  white-space: pre-wrap; /* Preserves whitespace and line breaks, but allows wrapping */
  font-family: monospace; /* Often used with pre-wrap for code blocks or pre-formatted text */
}

.standard-paragraph {
  white-space: normal; /* Default behavior: collapses multiple spaces and wraps text as needed */
}
